class Solution {
public:
    int maximumRows(std::vector<std::vector<int>>& matrix, int numSelect) {
        int m = matrix.size(), n = matrix[0].size();
        std::vector<int> rowMasks(m, 0);
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (matrix[i][j]) rowMasks[i] |= (1 << j);
            }
        }
        int maxCovered = 0;
        int totalMasks = 1 << n;
        for (int mask = 0; mask < totalMasks; mask++) {
            if (__builtin_popcount(mask) == numSelect) {
                int covered = 0;
                for (int rmask : rowMasks) {
                    if ((rmask & ~mask) == 0) covered++;
                }
                maxCovered = std::max(maxCovered, covered);
            }
        }
        return maxCovered;
    }
};

