var maximumRows = function(matrix, numSelect) {
    const m = matrix.length, n = matrix[0].length;
    const rowMasks = new Array(m).fill(0);
    for (let i = 0; i < m; i++) {
        for (let j = 0; j < n; j++) {
            if (matrix[i][j] === 1) rowMasks[i] |= (1 << j);
        }
    }

    function popcount(x) {
        let cnt = 0;
        while (x > 0) {
            cnt += (x & 1);
            x >>= 1;
        }
        return cnt;
    }

    let maxCovered = 0;
    const totalMasks = 1 << n;
    for (let mask = 0; mask < totalMasks; mask++) {
        if (popcount(mask) === numSelect) {
            let covered = 0;
            for (const rmask of rowMasks) {
                if ((rmask & ~mask) === 0) covered++;
            }
            if (covered > maxCovered) maxCovered = covered;
        }
    }
    return maxCovered;
};
